// Sky island terrain (tools/build-sky-islands.py): one painted stage per island level.
let terrainData=null;try{const r=await fetch('art/world/sky-terrain.json');if(!r.ok)throw Error('terrain');const d=await r.json();if(Array.isArray(d?.stages)&&d.stages.length)terrainData=d;}catch{terrainData=null;}
let archipelago=readArchipelago(null);try{archipelago=readArchipelago(localStorage.getItem(ARCHIPELAGO_KEY));}catch{}
