let actorPosition=P(...actorCell),walkClock=0,tickTime=0,sitFrom=null,sitTo=null,sitAt=0,walkGoalCell=null;
const currentCell=()=>nearestCell(state,actorPosition,actorCell);
try{const saved=JSON.parse(localStorage.getItem('pogeun-avatar-position-v1'));if(Array.isArray(saved)&&saved.length===2&&saved.every(Number.isFinite)){const cell=nearestCell(state,saved,[-1,-1]);if(cell[0]===state.avatar[0]&&cell[1]===state.avatar[1]&&lineClearPosition(saved))actorPosition=saved;}}catch{}
function lineClearPosition(point){const from=unproject(...P(...state.avatar)),to=unproject(...point);return preciseRoute(state,[state.avatar],P(...state.avatar),point).some(p=>Math.hypot(p[0]-to[0],p[1]-to[1])<.001);}
let shells=0;try{shells=readShells(localStorage.getItem(SHELL_KEY));}catch{}
let fishExchanged=0;try{const fish=Math.max(0,Math.floor(Number(localStorage.getItem(FISH_KEY))||0)),r=earn(shells,fish*FISH_PRICE);if(fish&&r.ok){shells=r.balance;fishExchanged=fish;localStorage.setItem(SHELL_KEY,shells);}localStorage.removeItem(FISH_KEY);}catch{}
function setShells(n){shells=n;try{localStorage.setItem(SHELL_KEY,shells);}catch{}walletLabel();}
function gain(n){const r=earn(shells,n);if(r.ok)setShells(r.balance);}
function saveArchipelago(){try{localStorage.setItem(ARCHIPELAGO_KEY,JSON.stringify(archipelago));}catch{say('섬 목록을 저장하지 못했어요. 저장 공간을 확인해 주세요.');}islandLabel();}
const islandLabel=()=>{const i=activeIsland(archipelago);$('island-switch').textContent=i.name+' · Lv'+i.level;};
const walletLabel=()=>{$('shell-wallet').innerHTML=shellIcon+'<span>조개 '+shells+'</span>';};
const weather=createWeather({world:$('world'),button:$('weather'),onUpdate:w=>{$('weather-status').textContent=weatherHeadline(w);$('weather-status').dataset.status=w.status;}});
const room=createRoom({world:$('world'),announce:say,onChange:()=>{render();$('walk-label').textContent=room.inside?'방바닥을 눌러 걸어가요':'잔디를 누르면 그곳으로 걸어가요';}});
const visitors=createAnimalVisitors({project:P,findRoute:route,getState:()=>state,redraw:render,announce:say,world:$('world'),reduced});
const freeCells=()=>terrainCells().filter(c=>passable(state,...c));
function placePet(){const free=freeCells().filter(c=>c[0]!==state.avatar[0]||c[1]!==state.avatar[1]);petCell=[...(free[Math.floor(free.length/2)]||state.avatar)];petPath=[];petTo=null;petStep=0;}
placePet();
const B={house:[0,0,418,416],bench:[428,80,355,322],daisy:[825,42,354,340],tulip:[1200,42,334,340],lavender:[0,401,380,324],pot:[425,460,307,257],pond:[773,445,415,280],tree:[1180,391,354,332],table:[18,720,363,300],bowl:[428,755,337,245],cushion:[779,741,420,267],lamp:[1270,716,191,305]};
function sprite(name,w,h){const own=artUrl('props',name);if(own)return`<image href="${own}" x="${-w/2}" y="${-h+8}" width="${w}" height="${h}" preserveAspectRatio="xMidYMax meet" pointer-events="none"/>`;const b=B[name],id='art'+(++seq);return`<svg x="${-w/2}" y="${-h+8}" width="${w}" height="${h}" viewBox="${b.join(' ')}" preserveAspectRatio="xMidYMax meet" aria-hidden="true" pointer-events="none"><defs><clipPath id="${id}"><rect x="${b[0]}" y="${b[1]}" width="${b[2]}" height="${b[3]}"/></clipPath></defs><image href="../littlepark/garden-atlas.webp" width="1536" height="1024" clip-path="url(#${id})"/></svg>`;}
function itemArt(p){if((p.kind==='path'||p.kind==='fence')&&artUrl('props',p.kind))return sprite(p.kind,...(p.kind==='path'?[70,40]:[90,75]));if(p.kind==='path')return'<path d="M-29-4l18-13 32 7 10 14-26 14-31-8z" fill="#e5ddbc" stroke="#b6b997" stroke-width="2"/><path d="M-17-5l11-5 17 3" fill="none" stroke="#f6f0d8" stroke-width="3"/>';if(p.kind==='fence')return'<g stroke="#a4ac8a" stroke-width="2" fill="#e4dfbe"><path d="M-38-31l76-19v9l-76 19zM-38-10l76-19v9l-76 19z"/><path d="M-28-39v48M0-46v49M28-53v49" stroke="#dedcc0" stroke-width="8"/></g>';
 if(p.kind==='pot'&&p.seed){if(growth(p)>=1)return sprite(p.seed,69,89);return sprite('pot',53,51)+`<g transform="translate(0 -24) scale(${.4+.6*growth(p)})"><path d="M0 0v-32" stroke="#72965b" stroke-width="4"/><path d="M0-12Q-27-38-22-15Q-10-5 0-9M0-21Q24-44 22-22Q10-12 0-16" fill="#97b47a"/></g>`;}
 if(p.kind==='field')return fieldArt(p);
 return sprite(p.kind,...({bench:[104,84],pot:[53,51],tree:[122,155],bowl:[44,34],pond:[119,79],table:[89,84],cushion:[79,58],lamp:[40,89]}[p.kind]));}
// Vegetable bed: tilled soil, sprouts while growing, the crop itself when ripe.
function fieldArt(p){const soil='<path d="M0-30l52 24-52 24-52-24z" fill="#a77d55" stroke="#7d5a3c" stroke-width="3"/><path d="M-30-16l52 24M-15-23l52 24M-45-9l52 24" stroke="#8b6646" stroke-width="3" opacity=".7"/>';if(!p.crop)return soil;const now=Date.now(),k=Math.min(1,(now-p.sown)/CROPS[p.crop].ms),spots=[[-22,-8],[0,-14],[22,-8],[-8,2],[14,2],[0,-2]];const fruit={carrot:'<path d="M-3-2l3 12 3-12z" fill="#ef8a3a"/>',potato:'<ellipse cy="2" rx="6" ry="4" fill="#c8a06a" stroke="#8f6c40"/>',strawberry:'<path d="M-5-1q5 13 10 0q-5-4-10 0z" fill="#e2485a"/>'}[p.crop];return soil+spots.map(([x,y])=>`<g transform="translate(${x} ${y}) scale(${.35+.65*k})"><path d="M0 0q-8-14-3-18M0 0q8-14 3-18M0 0v-16" stroke="#6f9a4a" stroke-width="3" fill="none"/>${k>=1?`<g transform="translate(0 -4)">${fruit}</g>`:''}</g>`).join('');}
function kitten(){if(momoReady)return momoMarkup()+'<ellipse class="object-hit" data-cat="1" cx="0" cy="-20" rx="24" ry="28" role="button" tabindex="0" aria-label="모모 만나기"/>';const b=petSleeping?[0,745,665,425]:[710,0,544,650],id='momo'+(++seq);return`<ellipse cy="5" rx="18" ry="6" fill="#63794b1a"/><svg x="-28" y="-49" width="56" height="56" viewBox="${b.join(' ')}" preserveAspectRatio="xMidYMax meet" aria-hidden="true" pointer-events="none"><defs><clipPath id="${id}"><rect x="${b[0]}" y="${b[1]}" width="${b[2]}" height="${b[3]}"/></clipPath></defs><image href="../littlepark/momo-atlas.webp" width="1254" height="1254" clip-path="url(#${id})"/></svg><ellipse class="object-hit" data-cat="1" cx="0" cy="-20" rx="24" ry="28" role="button" tabindex="0" aria-label="모모 만나기"/>`;}
function sittingPosition(t=performance.now()){if(!sitTo)return actorPosition;if(!sitFrom)return sitTo;const p=Math.min(1,(t-sitAt)/350),k=.5-.5*Math.cos(p*Math.PI);return[sitFrom[0]+(sitTo[0]-sitFrom[0])*k,sitFrom[1]+(sitTo[1]-sitFrom[1])*k];}
function actor(phase=0){return (humanMarkup({pose,face,back,time:performance.now()/1000})||person(state.outfit,{pose,time:performance.now()/1000,view:rigView(),flip:face<0,id:'island-person'}))+'<ellipse class="object-hit" data-avatar="1" cy="-65" rx="29" ry="54" role="button" tabindex="0" aria-label="내 아바타 옷장 열기"/>';}
function render(){$('scene').dataset.room=room.inside?'1':'0';if(room.inside){room.render();context();return;}const night=!weather.state.day&&weather.state.kind!=='unknown';$('game').dataset.theme=state.theme;$('scene').classList.toggle('decorating',mode==='decorate');const k=tile(),cells=terrainCells().map(([c,r])=>{const[x,y]=P(c,r);return`<path class="cell" data-cell="${c},${r}" role="button" tabindex="${mode==='decorate'?0:-1}" aria-label="잔디 ${c}열 ${r}행" d="M${x} ${y-GRID.hy}l${GRID.hx} ${GRID.hy}-${GRID.hx} ${GRID.hy}-${GRID.hx}-${GRID.hy}z"/>`;});
 const objs=state.items.map(p=>({depth:p.c+p.r,html:(()=>{const[x,y]=P(p.c,p.r),size=p.kind==='tree'?120:p.kind==='lamp'?90:p.kind==='pot'?85:70;return`<g data-node-key="item-${p.id}" data-depth="${p.c+p.r}" transform="translate(${x} ${y}) scale(${k})" class="${selected===p.id?'selected':''}"><ellipse class="chosen-mark" rx="37" ry="19"/><g transform="scale(${p.rot?-1:1} 1)" class="${p.kind==='tree'?'leaf':''}">${itemArt(p)}</g><rect class="object-hit" data-id="${p.id}" x="-33" y="${-size+5}" width="66" height="${size+8}" rx="15" role="button" tabindex="0" aria-label="${FURNITURE[p.kind].name}${p.seed?' · '+SEEDS[p.seed]:''}"/>${p.kind==='lamp'&&night?'<ellipse cy="-30" rx="45" ry="40" fill="url(#glow)" pointer-events="none"/>':''}</g>`;})()}));
 const seat=pose==='sit'?state.items.find(p=>p.id===selected):null;const[ax,ay]=seat?sittingPosition():actorPosition,[px,py]=P(...petCell);objs.push({depth:actorCell[0]+actorCell[1]+.15,html:`<g id="person" data-depth="${actorCell[0]+actorCell[1]+.15}" transform="translate(${ax} ${ay})">${actor()}</g>`},{depth:petCell[0]+petCell[1]+.1,html:`<g id="pet" data-depth="${petCell[0]+petCell[1]+.1}" transform="translate(${px} ${py})">${kitten()}</g>`});
 for(const a of state.animals)objs.push(livestockMarkup(a,P(a.c,a.r)));const visitor=visitors.render();if(visitor)objs.push(visitor);const st=stage();
 patchSvg($('world'),`<defs><linearGradient id="sky" gradientUnits="userSpaceOnUse" x1="0" y1="-320" x2="0" y2="1120"><stop stop-color="#c9c4e8"/><stop offset=".32" stop-color="#f5d8d0"/><stop offset=".58" stop-color="#fbeec9"/><stop offset="1" stop-color="#b9d8ec"/></linearGradient><radialGradient id="glow"><stop stop-color="#fff0b5" stop-opacity=".6"/><stop offset="1" stop-color="#fff0b5" stop-opacity="0"/></radialGradient><filter id="blur"><feGaussianBlur stdDeviation="12"/></filter></defs><rect x="-3000" y="-3000" width="6960" height="7000" fill="url(#sky)"/>${skyDecor()}${st?`<ellipse cx="480" cy="${st.y+st.height*.62}" rx="${st.width*.42}" ry="${st.height*.12}" fill="#8d7fb026" filter="url(#blur)"/><image id="island-ground" href="${st.file}" x="${st.x}" y="${st.y}" width="${st.width}" height="${st.height}" preserveAspectRatio="none"/><rect data-house="1" x="${st.house[0]}" y="${st.house[1]}" width="${st.house[2]}" height="${st.house[3]}" fill="transparent" role="button" tabindex="0" aria-label="우리 집 들어가기"/>`:fallbackIsland()}${cells.join('')}<g id="world-objects">${objs.sort((a,b)=>a.depth-b.depth).map(x=>x.html).join('')}</g><g id="effect"></g><g id="walk-target" pointer-events="none" opacity="0"><ellipse rx="14" ry="7" fill="none" stroke="#fff7d8" stroke-width="2"/></g>${weather.markup()}`);paintHumans($('world'),{pose,face,back,time:pose==='walk'?walkClock:performance.now()/1000});paintMomo($('world'),{resting:petSleeping,time:performance.now()/1000});camera();context();shelf();$('home').classList.toggle('active',mode==='walk');$('decorate').classList.toggle('active',mode==='decorate');}
// Pastel clouds and far-off islets behind the island (no sea below).
function skyDecor(){const cloud=(x,y,w)=>`<g transform="translate(${x} ${y}) scale(${w/100})" fill="#fff6f1" opacity=".92"><ellipse cx="0" cy="10" rx="58" ry="20"/><ellipse cx="-22" cy="-2" rx="26" ry="22"/><ellipse cx="14" cy="-10" rx="32" ry="28"/><ellipse cx="42" cy="4" rx="22" ry="16"/><ellipse cx="0" cy="18" rx="56" ry="9" fill="#f2c9cf" opacity=".6"/></g>`;const islet=(x,y,w)=>`<g transform="translate(${x} ${y}) scale(${w/60})" opacity=".55"><path d="M-30 0h60l-12 18-10 14-8-6-8 10-6-12-8 4z" fill="#b9a7c4"/><path d="M-32 0q32-12 64 0q-32 8-64 0z" fill="#a9c79a"/></g>`;return `<g id="sky-decor" pointer-events="none"><circle cx="760" cy="-40" r="44" fill="#fff6c8" opacity=".85"/>${cloud(120,40,150)}${cloud(820,120,120)}${cloud(-120,420,170)}${cloud(1060,520,160)}${cloud(260,900,190)}${cloud(780,960,170)}${islet(40,250,60)}${islet(900,340,46)}${islet(150,760,40)}</g>`;}
function fallbackIsland(){return'<path d="M474 223C619 210 749 282 792 382C835 476 704 560 551 594C407 627 250 564 174 464C120 391 187 294 306 256C360 236 420 225 474 223Z" fill="#a8cf86" stroke="#7fa560" stroke-width="6"/><path d="M174 464C230 640 420 720 551 594C704 560 835 476 792 382C800 560 620 760 480 760C330 760 180 640 174 464Z" fill="#9b7b5c"/>';}
function camera(){const aspect=$('scene').clientWidth/Math.max(1,$('scene').clientHeight),baseW=Math.max(960,800*aspect),w=baseW/zoom,h=baseW/aspect/zoom;$('world').setAttribute('viewBox',`${480-w/2} ${400-h/2} ${w} ${h}`);}
function say(t){$('toast').textContent=t;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));const at=currentCell();if(at[0]===state.avatar[0]&&at[1]===state.avatar[1])localStorage.setItem('pogeun-avatar-position-v1',JSON.stringify(actorPosition));}catch{storage=false;$('save-status').textContent='저장이 제한돼요. 이 창을 닫으면 진행이 사라질 수 있어요.';}}
function dispatch(e){const r=apply(state,e);if(!r.ok){say(r.why);return false;}state=r.state;save();if(r.earned)gain(r.earned);return true;}
function context(){if(room.inside){$('context').innerHTML='<div class="text">나의 작은 집<small>폭신한 침대와 러그 · 방바닥을 눌러 걸어요</small></div><button data-act="leave-house">밖으로 나가기</button>';return;}const p=state.items.find(x=>x.id===selected);if(!p){$('context').innerHTML=`<div class="text">${activeIsland(archipelago).name} · 조개 ${shells}<small>${state.items.some(x=>x.kind==='field')?'텃밭 수확과 가축 돌보기로 조개를 모아요':'꾸미기에서 텃밭을 놓고 씨앗을 뿌려 보세요'} · 사과 ${state.apples}개</small></div><button data-act="market">조개 상점</button>`;return;}let b='';if(mode==='decorate')b=`<button data-act="move">옮기기</button><button class="secondary" data-act="rotate">돌리기</button>${p.seed?'':'<button class="secondary" data-act="store">보관</button>'}`;else if(p.kind==='pot')b=p.seed?`<button data-act="water">${growth(p)>=1?'꽃 기록하기':'물 주기'}</button>`:'<button data-act="seed">씨앗 심기</button>';else if(p.kind==='bench'||p.kind==='cushion')b='<button data-act="sit">앉아서 쉬기</button>';else if(p.kind==='tree')b='<button data-act="harvest">사과 따기</button>';else if(p.kind==='field')b=p.crop?ripe(p)?`<button data-act="reap">수확하기 · 조개 ${CROPS[p.crop].shells}</button>`:'':'<button data-act="sow">씨앗 뿌리기</button>';else if(p.kind==='bowl')b='<button data-act="fill">물 채우기</button>';
 $('context').innerHTML=`<div class="text">${p.seed?SEEDS[p.seed]:p.crop?FURNITURE.field.name+' · '+CROPS[p.crop].name:FURNITURE[p.kind].name}<small>${moving?'옮길 빈 잔디 칸을 눌러 주세요':p.crop?ripe(p)?'잘 자랐어요. 수확하면 조개를 받아요.':`자라는 중 ${Math.floor(Math.min(1,(Date.now()-p.sown)/CROPS[p.crop].ms)*100)}%`:p.kind==='field'&&mode!=='decorate'?'씨앗을 뿌리고 수확해서 조개를 모아요':p.seed?growth(p)>=1?'활짝 피었어요. 시들지 않아요.':`자라는 중 ${Math.floor(growth(p)*100)}%`:mode==='decorate'?'자유롭게 배치하고 방향을 바꿔요':'가까이 걸어가서 함께해요'}</small></div><div class="buttons">${b}</div>`;}
function shelf(){const el=$('shelf'),scroll=el.scrollLeft;el.hidden=mode!=='decorate';if(mode==='decorate')el.innerHTML=Object.entries(FURNITURE).map(([kind,v])=>`<button class="item ${placing===kind?'active':''}" data-kind="${kind}"><svg viewBox="-75 -150 150 174" aria-hidden="true">${itemArt({kind})}</svg>${v.name}<small>${limit(state,kind)-state.items.filter(p=>p.kind===kind).length}개 남음</small></button>`).join('');el.scrollLeft=scroll;}
function cancelWalk(){if(pose==='sit'&&sitTo){actorPosition=[...sitTo];sitTo=null;sitFrom=null;}actorCell=currentCell();if(to||steps.length){dispatch({type:'walk',to:actorCell});}to=null;steps=[];pending=null;pose='idle';}
function walk(path,after=null,worldTarget=null){if(busy)return;if(!path.length){say('걸어갈 길이 막혀 있어요. 꾸미기에서 길을 비워 주세요.');return;}const continuing=pose==='walk';cancelWalk();steps=preciseRoute(state,path,actorPosition,worldTarget);walkGoalCell=[...path.at(-1)];stepIndex=0;pending=after;pose='walk';if(!continuing)walkClock=0;if(steps.length===1){finishWalk();return;}say('사뿐사뿐, 그쪽으로 가는 중이에요.');}
function finishWalk(){to=null;steps=[];if(walkGoalCell)actorCell=[...walkGoalCell];walkGoalCell=null;pose='idle';dispatch({type:'walk',to:actorCell});const action=pending;pending=null;render();if(action)perform(action);}
function nearAnimal(id){const a=state.animals.find(x=>x.id===id);if(!a)return;const v=LIVESTOCK[a.kind];if(!productReady(a)){say(`${v.name}의 ${v.product}이(가) 준비 중이에요 · ${Math.ceil((v.ms-(Date.now()-a.at))/1000)}초 남음`);return;}walk(approach(state,currentCell(),a),{type:'collect',id});}
function nearAction(type,id,seed){const p=state.items.find(x=>x.id===id);if(!p)return;walk(approach(state,currentCell(),p),type==='sow'?{type,id,crop:seed}:{type,id,seed});}
function perform(e){if(busy)return;busy=true;const target=state.items.find(p=>p.id===e.id)||state.animals.find(a=>a.id===e.id);if(target){face=P(target.c,target.r)[0]<P(...actorCell)[0]?-1:1;back=target.c+target.r<actorCell[0]+actorCell[1];}if(e.type==='sit'&&target){sitFrom=[...actorPosition];sitTo=P(target.c,target.r);if(humanChoice()==='male')sitTo[1]-=9;sitAt=performance.now();}pose=e.type==='water'||e.type==='fill'?'water':e.type==='plant'||e.type==='sow'||e.type==='reap'?'plant':e.type==='sit'?'sit':'idle';render();const[x,y]=P(...actorCell);if(['water','fill'].includes(e.type))$('effect').innerHTML=`<g transform="translate(${x+(face<0?-25:25)} ${y-36})" class="waterdrop" fill="#83b7b9"><ellipse rx="3" ry="6"/><ellipse cx="12" cy="4" rx="3" ry="5"/><ellipse cx="22" cy="-3" rx="3" ry="5"/></g>`;setTimeout(()=>{const before=shells,okay=dispatch(e);if(okay){const got=shells-before;say({water:'촉촉하게 물을 주었어요.',plant:'씨앗을 심었어요. 작은 잎이 고개를 내밀어요.',fill:'모모의 물그릇을 채웠어요.',harvest:'잘 익은 사과를 하나 땄어요.',sit:'잠깐, 구름 사이 바람을 느끼며 쉬어요.',sow:'씨앗을 뿌렸어요. 자라면 수확해 주세요.',reap:`수확했어요! 조개 ${got}개를 받았어요.`,collect:`${LIVESTOCK[target?.kind]?.product||'선물'}을(를) 받았어요! 조개 ${got}개.`}[e.type]||'');}if(!okay||e.type!=='sit')pose='idle';busy=false;render();},reduced?100:950);}
function modal(html){$('paper').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function closet(){cancelWalk();if(!ITEMS[slot])slot='top';const outfit=currentOutfit(),gender=humanChoice(),scroll=$('dialog').scrollTop;modal(`<small>MY WARDROBE · 모든 코디 무료</small><h2>오늘은 어떤 나?</h2><div class="looks"><button data-human="female" aria-pressed="${gender==='female'}" class="${gender==='female'?'chosen':''}">여자 캐릭터</button><button data-human="male" aria-pressed="${gender==='male'}" class="${gender==='male'?'chosen':''}">남자 캐릭터</button></div><div class="closet-stage"><img class="wardrobe-person" src="${humanSnapshot({preview:true})}" alt="${gender==='female'?'여자':'남자'} 캐릭터 현재 코디"><div class="caption">선택한 캐릭터 그대로, 옷만 갈아입어요</div></div><div class="closet-tabs">${Object.entries(SLOT_LABELS).map(([k,v])=>`<button data-slot="${k}" class="${slot===k?'active':''}">${v}</button>`).join('')}</div><div class="wardrobe">${ITEMS[slot].map(([v,label,color])=>`<button data-wear="${v}" class="${outfit[slot]===v?'selected':''}" aria-pressed="${outfit[slot]===v}"><span class="item-icon" data-item-icon="${v}"><img src="${humanSnapshot({preview:true,outfitOverride:{...outfit,[slot]:v}})}" alt="" loading="lazy"></span>${label}</button>`).join('')}</div><div class="looks">${savedLooks().map((_,i)=>`<button data-look="${i}">코디 ${i+1}</button>`).join('')}<button data-act="look-save">코디 저장</button></div><p class="closet-note">헤어는 다음 미용실 업데이트에서 만나요.</p><button class="primary" data-act="closet-done">이 모습으로 산책하기</button>`);$('dialog').scrollTop=scroll;}
function seeds(){modal(`<small>SEED POUCH</small><h2>처음 피울 꽃은?</h2><div class="seed-options">${Object.entries(SEEDS).map(([k,v])=>`<button data-seed="${k}"><svg viewBox="-45 -100 90 115">${sprite(k,70,95)}</svg>${v}</button>`).join('')}</div><p>꽃은 약 90초면 피어요.<br>물을 주면 조금 더 빨리 자라요.</p><small>자리를 비워도 자라고, 시들지 않아요.</small>`);}
function crops(){modal(`<small>VEGETABLE BED</small><h2>무엇을 키울까요?</h2><div class="seed-options">${Object.entries(CROPS).map(([k,v])=>`<button data-crop="${k}"><svg viewBox="-60 -45 120 70">${fieldArt({kind:'field',crop:k,sown:0})}</svg>${v.name}<small>${Math.round(v.ms/1000)}초 · 조개 ${v.shells}</small></button>`).join('')}</div><p>다 자란 작물을 수확하면 조개를 받아요.<br>자리를 비워도 자라고, 시들지 않아요.</p>`);}
function weatherPanel(){const w=weather.description();modal(`<small>SEOUL · POGEUN ISLAND</small><h2>${w.label}</h2><p>${w.when} · ${w.status}<br>${w.detail}</p><p>서울에 비가 오면 섬에도 비가 내리고,<br>눈이 오면 포근섬에도 눈이 내려요.</p><small>서울 대표 지점의 기상 모델 데이터여서 실제 거리의 날씨와 시차가 있을 수 있어요.<br>Weather data by <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a></small><button class="primary" data-act="weather-refresh">지금 다시 확인하기</button>`);}
function market(){const island=activeIsland(archipelago),grow=expandCost(island),more=newIslandCost(archipelago),row=(label,note,act,price,extra='')=>`<div class="journal-row shop-row"><span>${label}<small>${note}</small></span><button class="primary" ${act} ${price!==null&&shells>=price?'':'disabled'}>${price===null?'완료':'조개 '+price}</button>${extra}</div>`;
 modal(`<small>ISLAND EXCHANGE</small><h2>조개 상점</h2><div class="shell-total">${shellIcon}<strong>조개 ${shells}개</strong></div><p>텃밭 수확과 가축 돌보기로 조개를 모아요.</p>
 <h3>팔기</h3><div class="journal-row shop-row"><span>사과 ${state.apples}개<small>1개에 조개 5</small></span><button class="primary" data-act="sell-apple" ${state.apples?'':'disabled'}>1개 팔기</button></div>
 <h3>섬 가꾸기</h3>${row(`섬 넓히기 · Lv${island.level}${grow===null?'':' → '+(island.level+1)}`,grow===null?'가장 넓은 섬이에요':'잔디와 집이 함께 커져요','data-act="expand"',grow)}${row(`새 섬 만들기 · ${archipelago.islands.length}/4`,more===null?'더 만들 수 없어요':'빈 하늘섬을 하나 더 가꿔요','data-act="new-island"',more)}
 <h3>가축 입양 · ${state.animals.length}/${MAX_ANIMALS}</h3>${Object.entries(LIVESTOCK).map(([k,v])=>row(v.name,`${v.product} · ${Math.round(v.ms/1000)}초마다 조개 ${v.shells}`,`data-adopt="${k}"`,state.animals.length<MAX_ANIMALS?v.price:null)).join('')}
 <h3>물건 사기</h3>${Object.entries(FURNITURE).map(([k,v])=>row(v.name,`이 섬에 놓을 수 있는 수 ${limit(state,k)} → ${limit(state,k)+1}`,`data-buy="${k}"`,ITEM_PRICES[k])).join('')}
 <p>옷장의 기본 코디는 언제나 무료예요.</p>`);}
function sell(kind){const result=sale(shells,kind,state.apples);if(!result.ok)return;state.apples=result.stock;save();setShells(result.balance);market();say('조개 '+result.earned+'개를 모았어요.');}
function pay(cost){const r=spend(shells,cost);if(!r.ok){say(r.why);return false;}setShells(r.balance);return true;}
function buy(kind){const price=ITEM_PRICES[kind];if(price===undefined||shells<price){say('조개가 부족해요.');return;}const r=apply(state,{type:'buy',kind});if(!r.ok){say(r.why);return;}if(!pay(price))return;state=r.state;save();market();say(FURNITURE[kind].name+'을(를) 샀어요. 꾸미기에서 놓아 보세요.');}
function adopt(kind){const v=LIVESTOCK[kind];if(!v||shells<v.price){say('조개가 부족해요.');return;}const free=freeCells().filter(c=>c[0]!==state.avatar[0]||c[1]!==state.avatar[1]),mid=free.reduce((m,c)=>[m[0]+c[0]/free.length,m[1]+c[1]/free.length],[0,0]),sorted=free.sort((a,b)=>Math.hypot(a[0]-mid[0],a[1]-mid[1])-Math.hypot(b[0]-mid[0],b[1]-mid[1])),cell=[...sorted.slice(Math.floor(sorted.length*.35)),...sorted].find(c=>route(state,state.avatar,c).length&&[[1,0],[-1,0],[0,1],[0,-1]].some(([dc,dr])=>passable(state,c[0]+dc,c[1]+dr)));if(!cell){say('동물이 지낼 빈 잔디가 없어요. 섬을 넓혀 주세요.');return;}const r=apply(state,{type:'adopt',kind,c:cell[0],r:cell[1]});if(!r.ok){say(r.why);return;}if(!pay(v.price))return;state=r.state;save();render();market();say(v.name+'이(가) 섬 식구가 되었어요. '+v.product+'이(가) 준비되면 눌러 주세요.');}
// Changing island size or island: keep the layout (relocated onto the new terrain) and reset walking.
function resetActor(){steps=[];to=null;pending=null;pose='idle';selected=null;placing=null;moving=false;mode='walk';actorCell=[...state.avatar];actorPosition=P(...actorCell);try{localStorage.removeItem('pogeun-avatar-position-v1');}catch{}placePet();}
function growIsland(){const r=expand(archipelago,shells);if(!r.ok){say(r.why);return;}cancelWalk();save();archipelago=r.state;setShells(r.balance);saveArchipelago();applyTerrain();state=restore(JSON.stringify(state));save();resetActor();render();market();say(`섬이 넓어졌어요! 이제 Lv${activeIsland(archipelago).level} 섬이에요.`);}
function starterIsland(){const base=fresh(),cells=terrainCells(),[c,r]=cells[Math.floor(cells.length*.3)]||[4,4];base.avatar=cells[Math.floor(cells.length*.7)]||[4,7];base.items=[{id:1,kind:'field',c,r,rot:0},{id:2,kind:'pot',c,r,rot:0},{id:3,kind:'bench',c,r,rot:0}];base.next=4;base.welcomed=true;return restore(JSON.stringify(base));}
function loadIsland(saved){applyTerrain();state=saved?restore(saved):starterIsland();save();resetActor();render();}
function newIsland(){cancelWalk();save();const r=createIsland(archipelago,shells,JSON.stringify(state));if(!r.ok){say(r.why);return;}archipelago=r.state;setShells(r.balance);saveArchipelago();loadIsland(null);$('dialog').close();say(activeIsland(archipelago).name+'을(를) 만들었어요. 텃밭부터 가꿔 볼까요?');}
function goIsland(id){cancelWalk();save();const r=switchIsland(archipelago,id,JSON.stringify(state));if(!r.ok){say(r.why);return;}archipelago=r.state;saveArchipelago();loadIsland(r.saved);$('dialog').close();say(activeIsland(archipelago).name+'에 도착했어요.');}
function islands(){const more=newIslandCost(archipelago);modal(`<small>MY SKY ISLANDS</small><h2>나의 하늘섬</h2>${archipelago.islands.map(i=>`<div class="journal-row shop-row"><span>${i.name}<small>Lv${i.level} / ${MAX_LEVEL}</small></span>${i.id===archipelago.active?'<button disabled>지금 여기</button>':`<button class="primary" data-island="${i.id}">이동</button>`}</div>`).join('')}<div class="journal-row shop-row"><span>새 섬 만들기<small>${more===null?'섬은 4개까지예요':'조개 '+more+'개'}</small></span><button class="primary" data-act="new-island" ${more!==null&&shells>=more?'':'disabled'}>만들기</button></div><p>섬마다 가구·텃밭·가축 배치가 따로 저장돼요.<br>조개는 모든 섬이 함께 써요.</p>`);}
function journal(){modal(`<small>ISLAND JOURNAL</small><h2>우리 섬의 작은 기록</h2>${[['dressed','내 모습으로 갈아입기'],['planted','첫 씨앗 심기'],['watered','꽃에 물 주기'],['filled','모모 물그릇 채우기'],['friend','모모와 인사하기'],['rested','벤치에 앉아 쉬기'],['decorated','가구를 내 자리에 놓기'],['harvested','사과 따기'],['sowed','텃밭에 씨앗 뿌리기'],['reaped','작물 수확하고 조개 받기'],['ranched','가축 돌보기']].map(([k,v])=>`<div class="journal-row">${state.tasks[k]?'✓':'○'} ${v}</div>`).join('')}<p>조개 ${shells}개 · 하늘섬 ${archipelago.islands.length}개<br>모모와의 친밀도 ${state.hearts} / 10 · 사과 ${state.apples}개<br>가축 ${state.animals.length}마리 · 텃밭 ${state.items.filter(p=>p.kind==='field').length}개</p>${Object.entries(SEEDS).map(([k,v])=>`<div class="journal-row">${v}<small>${state.items.filter(p=>p.seed===k&&growth(p)>=1).length}송이 개화 · ${state.items.filter(p=>p.seed===k&&growth(p)<1).length}개 성장 중</small></div>`).join('')}<small>포근섬 0.4 · 이 기기에 자동 저장<br>조개는 게임 안에서만 쓰는 화폐예요. 현금 결제는 없어요.</small>`);}
function help(){modal('<small>WELCOME TO YOUR ISLAND</small><h2>여기서는,<br>내 취향대로 살아가요.</h2><p>옷장에서 나를 꾸미고,<br>잔디를 눌러 섬을 산책해요.</p><p>집을 누르면 우리 집에 들어가요.<br>텃밭과 가축을 돌보면 조개가 모여요.</p><p>모은 조개로 물건과 가축을 사고,<br>섬을 넓히거나 새 섬을 만들어요.</p><p>화분에 씨앗을 심고 물을 주거나<br>벤치에 앉아 잠깐 쉬어도 좋아요.</p><small>꾸미기에서는 가구를 놓고 옮길 수 있어요.<br>기본 의상과 가구는 모두 무료예요.</small><button class="primary" data-act="start">내 모습부터 골라볼래요</button><button class="primary" data-act="begin-walk">먼저 섬 둘러보기</button>');}
async function photograph(){if(photoBusy)return;photoBusy=true;say('우리 섬의 모습을 사진에 담고 있어요.');try{const clone=$('world').cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','960');clone.setAttribute('height','800');clone.setAttribute('viewBox','0 0 960 800');for(const [i,fo] of [...clone.querySelectorAll('foreignObject')].entries()){const canvas=$('world').querySelectorAll('foreignObject canvas')[i];if(!canvas)continue;const im=document.createElementNS('http://www.w3.org/2000/svg','image');for(const a of ['x','y','width','height'])im.setAttribute(a,fo.getAttribute(a));im.setAttribute('href',canvas.toDataURL());fo.replaceWith(im);}clone.querySelectorAll('.cell,.object-hit,.chosen-mark').forEach(el=>el.remove());const cache=new Map();for(const image of clone.querySelectorAll('image')){const url=new URL(image.getAttribute('href'),location.href).href;if(!cache.has(url)){const blob=await(await fetch(url)).blob();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});cache.set(url,data);}image.setAttribute('href',cache.get(url));}const svg=new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml'}),url=URL.createObjectURL(svg),img=new Image();try{img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=960;canvas.height=860;const c=canvas.getContext('2d');c.fillStyle='#fff9e9';c.fillRect(0,0,960,860);c.drawImage(img,0,0,960,800);c.fillStyle='#78876a';c.font='20px sans-serif';c.textAlign='center';c.fillText('MY LITTLE ISLAND · 포근섬',480,838);photoUrl=canvas.toDataURL('image/png');}finally{URL.revokeObjectURL(url);}modal(`<small>OUR ISLAND MEMORY</small><h2>오늘의 포근섬</h2><img class="photo" src="${photoUrl}" alt="지금 코디한 아바타와 꾸민 섬의 기념사진"><a class="primary download" href="${photoUrl}" download="my-little-island.png">사진 저장하기</a><p>코디와 배치를 바꾸면<br>사진에도 그대로 담겨요.</p>`);say('우리 섬의 오늘을 담았어요.');}catch{say('사진을 불러오지 못했어요. 잠시 뒤 다시 눌러 주세요.');}finally{photoBusy=false;}}
$('close').onclick=()=>$('dialog').close();$('closet').onclick=closet;$('journal').onclick=journal;$('help').onclick=help;$('camera').onclick=photograph;$('weather').onclick=weatherPanel;$('shell-wallet').onclick=market;$('zoom-in').onclick=()=>{zoom=Math.min(1.45,zoom+.15);camera();};$('zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.15);camera();};$('home').onclick=()=>{if(room.inside){room.leave();return;}mode='walk';selected=null;placing=null;moving=false;render();say('잔디를 누르면 그곳으로 걸어가요.');};$('decorate').onclick=()=>{if(room.inside){say('방에는 침대와 러그를 준비했어요. 방 꾸미기는 다음에 열려요.');return;}cancelWalk();mode='decorate';render();say('주머니에서 물건을 골라 빈 잔디 칸에 놓아요.');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.human){chooseHuman(b.dataset.human);render();closet();return;}if(b.dataset.slot){slot=b.dataset.slot;closet();}if(b.dataset.wear){wearItem(slot,b.dataset.wear);state.tasks.dressed=true;save();render();closet();}if(b.dataset.look!==undefined){loadLook(Number(b.dataset.look));render();closet();}if(b.dataset.kind){placing=b.dataset.kind;moving=false;selected=null;shelf();context();say(FURNITURE[placing].name+' · 빈 잔디 칸에 놓아 주세요.');}if(b.dataset.seed){$('dialog').close();nearAction('plant',selected,b.dataset.seed);}if(b.dataset.crop){$('dialog').close();nearAction('sow',selected,b.dataset.crop);}if(b.dataset.buy)buy(b.dataset.buy);if(b.dataset.adopt)adopt(b.dataset.adopt);if(b.dataset.island)goIsland(Number(b.dataset.island));const act=b.dataset.act;if(act==='weather-refresh'){weather.refresh(true);say('서울 날씨를 다시 확인하고 있어요.');}if(act==='sell-apple')sell('apple');if(act==='market')market();if(act==='expand')growIsland();if(act==='new-island')newIsland();if(act==='sow')crops();if(act==='leave-house')room.leave();if(act==='closet')closet();if(act==='look-save'){saveLook();closet();}if(act==='closet-done'){$('dialog').close();mode='walk';render();say('새 코디로 산책을 시작해 볼까요?');}if(act==='start'){dispatch({type:'welcome'});closet();}if(act==='begin-walk'){dispatch({type:'welcome'});$('dialog').close();}if(act==='seed')seeds();if(['water','fill','sit','harvest','reap'].includes(act))nearAction(act,selected);if(act==='move'){moving=true;placing=null;say('옮길 빈 잔디 칸을 눌러 주세요.');context();}if(act==='rotate'){if(dispatch({type:'rotate',id:selected}))render();}if(act==='store'){if(dispatch({type:'store',id:selected})){selected=null;render();say('주머니에 보관했어요. 다시 꺼낼 수 있어요.');}}});
function pick(target,point=null){if(busy)return;if(target.closest('[data-house]')){cancelWalk();room.enter();return;}const animal=target.closest('[data-animal]');if(animal){if(mode==='walk')nearAnimal(Number(animal.dataset.animal));else say('가축은 그 자리에서 지내요. 산책 모드에서 돌봐 주세요.');return;}if(target.closest('[data-visitor]')){visitors.greet();return;}if(target.closest('[data-avatar]')){closet();return;}if(target.closest('[data-cat]')){const p={c:petCell[0],r:petCell[1]};const path=approach(state,currentCell(),p);walk(path,{type:'pet'});return;}const item=target.closest('[data-id]');if(item){selected=Number(item.dataset.id);moving=false;placing=null;context();if(mode==='walk')say('아래에서 함께할 행동을 골라 주세요.');render();return;}const cell=target.closest('[data-cell]');if(!cell)return;const[c,r]=cell.dataset.cell.split(',').map(Number);if(mode==='decorate'){if(moving){if(dispatch({type:'move',id:selected,c,r})){moving=false;render();say('내가 고른 자리에 놓았어요.');}}else if(placing){if(dispatch({type:'place',kind:placing,c,r})){selected=state.next-1;render();say('섬에 새로운 자리가 생겼어요.');}}else say('물건을 먼저 골라 주세요.');}else{const target=$('world').querySelector('#walk-target'),[tx,ty]=point||P(c,r);target?.setAttribute('transform',`translate(${tx} ${ty})`);target?.setAttribute('opacity','1');setTimeout(()=>target?.setAttribute('opacity','0'),900);walk(route(state,currentCell(),[c,r]),null,point);}}
$('world').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,id:Number(e.target.closest('[data-id]')?.dataset.id),target:e.target,moved:false};});$('world').addEventListener('pointermove',e=>{if(pointer&&Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>12)pointer.moved=true;});$('world').addEventListener('pointerup',e=>{const p=pointer;pointer=null;if(p?.moved&&p.id&&mode==='decorate'){const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('world').getScreenCTM().inverse());const[c,r]=unproject(pt.x,pt.y).map(Math.round);selected=p.id;if(dispatch({type:'move',id:p.id,c,r})){render();say('새 자리에 놓았어요.');}return;}if(!p?.moved){if(room.inside){const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('world').getScreenCTM().inverse());room.pick(e.target,pt.x,pt.y);}else{const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('world').getScreenCTM().inverse());pick(e.target,[pt.x,pt.y]);}}});$('world').addEventListener('pointercancel',()=>pointer=null);$('world').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(room.inside)room.pick(e.target,560,580);else pick(e.target);}});
function sortDepth(){const group=$('world').querySelector('#world-objects');if(!group)return;for(const id of ['person','pet','animal-visitor']){const el=group.querySelector('#'+id);if(!el)continue;const numbers=el.getAttribute('transform')?.match(/-?[\d.]+/g)?.map(Number);if(numbers?.length>=2){const[c,r]=unproject(numbers[0],numbers[1]);el.dataset.depth=c+r+.15;}}const ordered=[...group.children].sort((a,b)=>Number(a.dataset.depth)-Number(b.dataset.depth));let cursor=group.firstElementChild;for(const node of ordered){if(node!==cursor)group.insertBefore(node,cursor);cursor=node.nextElementSibling;}}
function tick(t){const dt=tickTime?Math.min(.04,(t-tickTime)/1000):0;tickTime=t;weather.tick(t,reduced);if(room.inside){visitors.tick(t,true);if(!$('dialog').open)room.tick(t);requestAnimationFrame(tick);return;}visitors.tick(t,busy||!!pointer||$('dialog').open||mode==='decorate');if(t-lastFrame>0&&!document.hidden&&!$('dialog').open){lastFrame=t;if(!steps.length&&!to&&!reduced){const el=$('person');if(el){if(pose==='sit'&&sitTo&&sitFrom){const p=Math.min(1,(t-sitAt)/350),k=.5-.5*Math.cos(p*Math.PI);el.setAttribute('transform',`translate(${sitFrom[0]+(sitTo[0]-sitFrom[0])*k} ${sitFrom[1]+(sitTo[1]-sitFrom[1])*k})`);}paintHumans(el,{pose,face,back,time:t/1000});}}if(steps.length){if(!to&&stepIndex<steps.length-1){from=[...actorPosition];to=P(...steps[++stepIndex]);started=0;const dc=steps[stepIndex][0]-actorCell[0],dr=steps[stepIndex][1]-actorCell[1];face=to[0]<from[0]?-1:1;back=to[1]<from[1]&&Math.abs(to[1]-from[1])>Math.abs(to[0]-from[0])*.35;}if(to){started+=dt*1000;walkClock+=dt;const a=reduced?1:Math.min(1,started/Math.max(16,Math.hypot(to[0]-from[0],to[1]-from[1])/WALK_SPEED*1000)),x=from[0]+(to[0]-from[0])*a,y=from[1]+(to[1]-from[1])*a;actorPosition=[x,y];const el=$('person');if(el){el.setAttribute('transform',`translate(${x} ${y})`);paintHumans(el,{pose,face,back,time:walkClock});}if(a===1){actorCell=[...steps[stepIndex]];to=null;if(stepIndex===steps.length-1)finishWalk();}}}
 if(!busy&&!pointer&&t>petWait&&!reduced){if(!petTo){if(!petPath.length||petStep>=petPath.length-1){const free=freeCells(),goal=free.length?free[Math.floor(t/9000)*7919%free.length]:petCell;petPath=route(state,petCell,goal);petStep=0;}if(petPath.length>1){petFrom=P(...petCell);petTo=P(...petPath[++petStep]);petStart=0;petSleeping=false;}}if(petTo){petStart+=dt*1000;const a=Math.min(1,petStart/950),x=petFrom[0]+(petTo[0]-petFrom[0])*a,y=petFrom[1]+(petTo[1]-petFrom[1])*a,el=$('pet');if(el)el.setAttribute('transform',`translate(${x} ${y})`);if(a===1){petCell=[...petPath[petStep]];petTo=null;if(petStep===petPath.length-1){petWait=t+8000;petSleeping=state.hearts>1;if(el&&!momoReady)el.innerHTML=kitten();}}}}
 }if(!$('dialog').open){paintLivestock($('world'),state.animals,t/1000,reduced);}if(!$('dialog').open)paintMomo($('world'),{walking:!!petTo,dx:petTo?petTo[0]-petFrom[0]:0,dy:petTo?petTo[1]-petFrom[1]:0,resting:petSleeping,time:t/1000});sortDepth();requestAnimationFrame(tick);}requestAnimationFrame(tick);
let stages='';setInterval(()=>{if(busy||pointer||steps.length||$('dialog').open)return;const now=Date.now(),x=state.items.filter(p=>p.seed||p.crop).map(p=>p.crop?Math.floor(Math.min(1,(now-p.sown)/CROPS[p.crop].ms)*4):growth(p)>=1?'flower':'leaf').join()+'|'+state.animals.map(a=>productReady(a,now)).join();if(stages!==x){stages=x;render();}else if(selected)context();},1800);
$('island-switch').onclick=islands;new ResizeObserver(camera).observe($('scene'));walletLabel();islandLabel();render();say(fishExchanged?`바다가 사라져 물고기 ${fishExchanged}마리를 조개 ${fishExchanged*FISH_PRICE}개로 바꿔 드렸어요.`:'잔디를 눌러 걸어가거나, 텃밭과 가축을 돌봐 조개를 모아요.');if(!state.welcomed)help();
